// From the graph: E3 = ¬C1 · E2 = C1∧¬C2 · E1 = C1∧C2∧(C3∨C4) · E4 = C1∧C2∧¬(C3∨C4)
const EFFECTS = {
  FTTT: ['E3'],
  TFTT: ['E2'],
  TTTF: ['E1'],
  TTFT: ['E1'],   // the approved retake request (C4) makes up for too many absences
  TTFF: ['E4'],
  TFFF: ['E2'],
  FFFF: ['E3'],
};
const RULE_COUNT = 5; // (F,–,–,–) (T,F,–,–) (T,T,T,–) (T,T,F,T) (T,T,F,F)

// ON point: valid, exactly on the boundary. OFF point: one step outside, breaking ONLY that boundary.
const DOMAIN = {
  B1: { on: [7, 2], off: [6, 2] },     // start = 7
  B3: { on: [10, 1], off: [10, 0] },   // duration = 1
  B4: { on: [10, 3], off: [10, 4] },   // duration = 3 (10 + 4 = 14 still satisfies the sum)
  B5: { on: [18, 3], off: [19, 3] },   // start + duration = 21
};
// start <= 20 is implied: start + duration <= 21 and duration >= 1 give start <= 20.
const REDUNDANT = 'start <= 20';
